       height: auto; /* 高度自动调整，保持比例 */
       object-fit: contain; /* 改为contain，确保完整显示 */
       display: block;
       margin: auto;
       min-height: 200px; /* 设置最小高度 */
   }
   /* 新增图片容器样式 */
   .img-container {
       width: 100%;
       height: 100%;
       display: flex;
       flex-direction: column;
       justify-content: center;
       align-items: center;
       overflow: hidden;
   }
</style>

<table style="width: 100%; border-collapse: collapse;">
   <tr>
       <td style="width: 35%; border:1px solid #000; border-right: none;">
           <img src="/files/image_2023_08_24T15_16_35_199Z.png" style="height: 50px;">
       </td>
       <td style="width: 55%; text-align: right; border:1px solid #000; border-left: none;">
           <h2 style="margin: 0; font-weight: bold; font-size: 25px;">
               Production Briefing Form
           </h2>
       </td>
   </tr>
</table>

<div class="section-title"> </div>

{% if doc.project %}
    {% set project_doc = frappe.get_doc("Project", doc.project) %}
{% endif %}

<table style="width: 100%; font-size: 11px; table-layout: fixed;">
   <tr>
       <td style="width:50%;">
           <strong class="lbl">ID:</strong> {{ doc.name }}
       </td>
       <td style="width:50%;">
           <strong class="lbl">Quotation:</strong>
           {{ project_doc.project_name if doc.project and project_doc.project_name else "Not Set" }}
       </td>
   </tr>

   <tr>
       <td>
           <strong class="lbl">Project:</strong> {{ doc.project or "Not Set" }}
       </td>
       <td>
           <strong class="lbl">Sales Person:</strong> {{ doc.sales_person or "Not Set" }}
       </td>
   </tr>

   <tr>
       <td>
           <strong class="lbl">Foreman:</strong>
           {% if doc.project and project_doc.custom_delivery_incharge %}
               {{ frappe.db.get_value("User", project_doc.custom_delivery_incharge, "full_name") or project_doc.custom_delivery_incharge }}
           {% else %}
               Not Set
           {% endif %}
       </td>
       <td>
           <strong class="lbl">Delivery Date:</strong>
           {{ frappe.utils.formatdate(doc.expected_delivery_date) if doc.expected_delivery_date else "Not Set" }}
       </td>
   </tr>

   <tr>
       <td>
           <strong class="lbl">Sales Confirmation Date:</strong>
           {{ frappe.utils.formatdate(doc.sales_confirmation_date) if doc.sales_confirmation_date else "Not Set" }}
       </td>
       <td>
           <strong class="lbl">Production Date:</strong>
           {{ frappe.utils.formatdate(doc.approved_date) if doc.approved_date else "" }}
       </td>
   </tr>
</table>


<table>
   <tr>
       <th style="width:6%;">SL NO</th>
       <th style="width:50%;">DESCRIPTION</th>
       <th style="width:10%;">QUANTITY</th>
       <th style="width:34%;">IMAGE</th> <!-- 调整图片列宽度 -->
   </tr>

   {% for row in doc.briefing_items or [] %}
   <tr>
       <td class="center">{{ loop.index }}</td>
       <td class="desc-td">
           <div class="item-name">{{ row.item_name }}</div>
           <table class="desc-table">
               <tr><td class="desc-label">Code:</td><td class="desc-value">{{ row.item_code or "N/A" }}</td></tr>
               <tr><td class="desc-label">Application:</td><td class="desc-value">{{ row.application or "N/A" }}</td></tr>
               <tr><td class="desc-label">Floor:</td><td class="desc-value">{{ row.custom_floor or "N/A" }}</td></tr>
               <tr><td class="desc-label">Place of Fixing:</td><td class="desc-value">{{ row.application or "N/A" }}</td></tr>
               <tr><td class="desc-label">Door Type:</td><td class="desc-value">{{ row.item_name or "N/A" }}</td></tr>
               <tr><td class="desc-label">Product Type:</td><td class="desc-value">{{ row.product or "N/A" }}</td></tr>
               <tr><td class="desc-label">Shutter Type:</td><td class="desc-value">{{ row.shutter_type or "N/A" }}</td></tr>
               <tr><td class="desc-label">Category:</td><td class="desc-value">{{ row.category or "N/A" }}</td></tr>
               <tr><td class="desc-label">Open Type:</td><td class="desc-value">{{ row.custom_open_type or "N/A" }}</td></tr>
               <tr><td class="desc-label">Product Grade:</td><td class="desc-value">{{ row.flush_grade or "N/A" }}</td></tr>
               <tr><td class="desc-label">Product Size:</td><td class="desc-value">{{ row.product_size or "N/A" }}</td></tr>
               <tr><td class="desc-label">Product Thickness:</td><td class="desc-value">{{ row.product_thickness or "N/A" }}</td></tr>
               <tr><td class="desc-label">Theranai Type:</td><td class="desc-value">{{ row.custom_theranai_type or "N/A" }}</td></tr>

               <!-- LAMINATED DOOR DESIGN section - only show if laminate is selected -->
               {% if row.laminate == 1 or row.custom_laminates %}

               {% set front_side = row.custom_laminates.split("Back Side:")[0].strip() if row.custom_laminates else "" %}
               {% set back_side = row.custom_laminates.split("Back Side:")[1].strip() if row.custom_laminates and "Back Side:" in row.custom_laminates else "" %}

               <tr>
                   <td colspan="2" style="font-weight:900; background-color:#333333; color:#ffffff; padding:4px 3px !important; text-align:center; font-size:10px; letter-spacing:0.5px; border:1px solid #333;">
                       LAMINATED DOOR DESIGN
                   </td>
               </tr>

               {% if row.laminate_thickness %}
               <tr>
                   <td class="desc-label">Laminate Thickness:</td>
                   <td class="desc-value">{{ row.laminate_thickness }}</td>
               </tr>
               {% endif %}

               {% if front_side %}
               <tr>
                   <td class="desc-label">Front Side Code:</td>
                   <td class="desc-value">{{ front_side }}</td>
               </tr>
               {% endif %}

               {% if back_side %}
               <tr>
                   <td class="desc-label">Back Side Code:</td>
                   <td class="desc-value">{{ back_side }}</td>
               </tr>
               {% endif %}

           {% endif %}

               {% if row.category == "Wood" %}
               <tr>
                   <td colspan="2" style="font-weight:900; background-color:#333333; color:#ffffff; padding:4px 3px !important; text-align:center; font-size:10px; letter-spacing:0.5px; border:1px solid #333;">
                       WOOD DETAILS
                   </td>
               </tr>
               <tr><td class="desc-label">Wood Grade:</td><td class="desc-value">{{ row.wood_grade or "N/A" }}</td></tr>
               <tr><td class="desc-label">Wood Type:</td><td class="desc-value">{{ row.wood_type or "N/A" }}</td></tr>
               <tr><td class="desc-label">Rebate Thickness:</td><td class="desc-value">{{ row.rebate_thickness or "N/A" }}</td></tr>

               {% endif %}
               {% if row.grill == 1 %}
               <tr>
                   <td colspan="2"
                       style="font-weight:900;
                              background-color:#333333;
                              color:#ffffff;
                              padding:4px 3px !important;
                              text-align:center;
                              font-size:10px;
                              letter-spacing:0.5px;
                              border:1px solid #333;">
                       GRILL DETAILS
                   </td>
               </tr>

               <tr>
                   <td class="desc-label">Grill Model:</td>
                   <td class="desc-value">
                       {{ row.grill_details or "N/A" }}
                   </td>
               </tr>

               {% endif %}
               {% if row.threshold == 1 %}
               <tr>
                   <td colspan="2"
                       style="font-weight:900;
                              background-color:#333333;
                              color:#ffffff;
                              padding:4px 3px !important;
                              text-align:center;
                              font-size:10px;
                              letter-spacing:0.5px;
                              border:1px solid #333;">
                       THRESHOLD DETAILS
                   </td>
               </tr>

               <tr>
                   <td class="desc-label">Threshold Thickness:</td>
                   <td class="desc-value">
                       {{ row.threshold_thickness or "N/A" }}
                   </td>
               </tr>

               {% endif %}
               {% if row.veneer == 1 %}
               <tr>
                   <td colspan="2"
                       style="font-weight:900;
                              background-color:#333333;
                              color:#ffffff;
                              padding:4px 3px !important;
                              text-align:center;
                              font-size:10px;
                              letter-spacing:0.5px;
                              border:1px solid #333;">
                       VENEER DETAILS
                   </td>
               </tr>

               <tr>
                   <td class="desc-label">Veneer:</td>
                   <td class="desc-value">
                       Included
                   </td>
               </tr>

               {% endif %}
               {% if row.epoxy == 1 %}
               <tr>
                   <td colspan="2"
                       style="font-weight:900;
                              background-color:#333333;
                              color:#ffffff;
                              padding:4px 3px !important;
                              text-align:center;
                              font-size:10px;
                              letter-spacing:0.5px;
                              border:1px solid #333;">
                       EPOXY DETAILS
                   </td>
               </tr>

               <tr>
                   <td class="desc-label">Epoxy:</td>
                   <td class="desc-value">
                       Included
                   </td>
               </tr>

               {% endif %}
               {% if row.load_bearing == 1 %}
               <tr>
                   <td colspan="2"
                       style="font-weight:900;
                              background-color:#333333;
                              color:#ffffff;
                              padding:4px 3px !important;
                              text-align:center;
                              font-size:10px;
                              letter-spacing:0.5px;
